import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/tmp/uploads')
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif', 'pdf'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_filename(filename):
    # Remove directory traversal attempts
    filename = filename.replace('..', '').replace('/', '').replace('\\', '')
    return filename

@app.route('/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using system utility."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if uploaded.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    # Get user-specified output format options
    output_format = request.form.get('format', 'pdf')
    page_range = request.form.get('pages', 'all')
    resolution = request.form.get('dpi', '150')

    # Validate resolution is numeric
    if not resolution.isdigit():
        return jsonify({'error': 'DPI must be numeric'}), 400

    # Validate output format
    if output_format not in ('pdf', 'png', 'tiff'):
        return jsonify({'error': 'Invalid format'}), 400

    safe_name = sanitize_filename(uploaded.filename)
    if not safe_name or not allowed_file(safe_name):
        return jsonify({'error': 'Invalid file type'}), 400

    # Save uploaded file
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    input_path = os.path.join(UPLOAD_DIR, safe_name)
    uploaded.save(input_path)

    # Build conversion command
    output_path = os.path.join(UPLOAD_DIR, f'output_{os.getpid()}.{output_format}')

    # Construct the conversion command with user parameters
    cmd = f'convert -density {resolution} "{input_path}"'

    if page_range != 'all':
        # User can specify page range like "1-3" or "1,2,5"
        cmd += f' -pages {page_range}'

    cmd += f' "{output_path}"'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:200]
            }), 500

        # Return success with output path
        return jsonify({
            'status': 'success',
            'output': output_path,
            'size': os.path.getsize(output_path)
        })

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)


@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'pid': os.getpid()})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
